import { createContext, useContext, useEffect, useMemo, useState } from "react";
import { Link, NavLink, Route, Routes, useNavigate, useParams, useSearchParams } from "react-router-dom";

import { adminApi, AdminApiError, type AdminDiagnostics, type AdminMapping, type AdminOverview, type AdminRecord, type AdminSetting, type AuditCatalog, type AuditEvent, type AuditList, type AuditValue } from "../api/admin";
import { AuditDiff } from "../components/AuditDiff";

type Remote<T> = { state: "loading" } | { state: "error"; error: AdminApiError } | { state: "ready"; value: T };

type AdminSessionState = { ready: boolean; setReady: (ready: boolean) => void };
const AdminSessionContext = createContext<AdminSessionState | undefined>(undefined);

function useAdminSession(): AdminSessionState {
  const value = useContext(AdminSessionContext);
  if (!value) throw new Error("Administrator session state is unavailable.");
  return value;
}

function useRemote<T>(load: (signal: AbortSignal) => Promise<T>, key: string): Remote<T> {
  const [state, setState] = useState<Remote<T>>({ state: "loading" });
  useEffect(() => {
    const controller = new AbortController();
    setState({ state: "loading" });
    load(controller.signal)
      .then((value) => { if (!controller.signal.aborted) setState({ state: "ready", value }); })
      .catch((error: unknown) => {
        if (!controller.signal.aborted) {
          setState({ state: "error", error: error instanceof AdminApiError ? error : new AdminApiError("The Administrator request failed.", 0) });
        }
      });
    return () => controller.abort();
  // `load` is intentionally represented by `key`: callers supply a stable
  // request identity so a render-local closure cannot cause a fetch loop.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key]);
  return state;
}

function formatTime(value: string) {
  return new Intl.DateTimeFormat(undefined, {
    year: "numeric",
    month: "short",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
    second: "2-digit",
    timeZoneName: "short",
  }).format(new Date(value));
}

function copy(value: string) {
  void navigator.clipboard?.writeText(value);
}

function ErrorState({ error }: { error: AdminApiError }) {
  if (error.status === 401 || error.status === 403) {
    return <section className="state-panel denied" aria-labelledby="denied-title"><h1 id="denied-title">Administrator access required</h1><p>Administrator data was not returned. Sign in through an approved Administrator identity, then try again.</p>{error.requestId ? <p>Request ID: <code>{error.requestId}</code></p> : null}</section>;
  }
  if (error.status === 404) {
    return <section className="state-panel error" aria-labelledby="not-found-title"><h1 id="not-found-title">Audit event not found</h1><p>The requested audit event is not available to this Administrator identity.</p>{error.requestId ? <p>Request ID: <code>{error.requestId}</code></p> : null}</section>;
  }
  return <section className="state-panel error" aria-labelledby="error-title"><h1 id="error-title">Administrator data could not load</h1><p>{error.message}</p>{error.requestId ? <p>Request ID: <code>{error.requestId}</code></p> : null}</section>;
}

function LoadingState() { return <section className="state-panel" aria-live="polite"><h1>Loading Administrator data</h1><p>The current server response is being retrieved.</p></section>; }

function AdminLayout({ children }: { children: React.ReactNode }) {
  return <div className="admin-layout"><a className="skip-link" href="#admin-content">Skip to main content</a><aside className="admin-sidebar"><div className="admin-brand"><span>EOAT Atlas</span><strong>Administration</strong></div><nav aria-label="Administration"><NavLink end to="/admin">Overview</NavLink><NavLink to="/admin/audit">Audit ledger</NavLink><NavLink to="/admin/data">Data</NavLink><NavLink to="/admin/data/relationships">Relationships</NavLink><NavLink to="/admin/data/documents">Documents</NavLink><NavLink to="/admin/data/photos">Photos</NavLink><NavLink to="/admin/data/bulk">Bulk workflow</NavLink><NavLink to="/admin/settings">Settings</NavLink><NavLink to="/admin/access">Access</NavLink><NavLink to="/admin/system">System</NavLink><NavLink to="/admin/diagnostics">Diagnostics</NavLink></nav><a className="return-link" href="/">← Return to EOAT Atlas</a></aside><main id="admin-content" className="admin-main" tabIndex={-1}>{children}</main></div>;
}

function PageTitle({ title, children }: { title: string; children?: React.ReactNode }) {
  return <header className="page-heading"><p className="eyebrow">Administration</p><h1>{title}</h1>{children}</header>;
}

function EventLink({ event }: { event: AuditEvent }) { return <Link to={`/admin/audit/events/${encodeURIComponent(event.event_id)}`}>{event.action} · {event.entity.display_id ?? event.entity.id}</Link>; }

function OverviewPage() {
  const remote = useRemote<AdminOverview>((signal) => adminApi.overview(signal), "overview");
  if (remote.state === "loading") return <LoadingState />;
  if (remote.state === "error") return <ErrorState error={remote.error} />;
  const { value } = remote;
  const metrics = [
    ["Events today (UTC)", value.metrics.events_today], ["Events, last 24 hours", value.metrics.events_last_24_hours],
    ["Successful", value.metrics.successful_events_last_24_hours], ["Failed", value.metrics.failed_events_last_24_hours],
    ["Denied", value.metrics.denied_events_last_24_hours], ["Security", value.metrics.security_events_last_24_hours],
    ["Unique actors", value.metrics.unique_actors_last_24_hours],
  ];
  return <><PageTitle title="Administrative overview"><p>Server-observed {formatTime(value.observation_time_utc)}. Audit activity uses authoritative UTC event timestamps.</p></PageTitle><section className="card-grid status-grid" aria-label="System identity"><StatusCard label="API" value={value.api_status} detail={`Contract ${value.api_version}`} /><StatusCard label="Database" value={value.database_status} detail={`Schema ${value.schema_revision ?? "unknown"}`} /><StatusCard label="Audit" value={value.audit_status} detail={`Schema v${value.audit_schema_version}`} /><StatusCard label="Writes" value={value.writes_enabled ? "enabled" : "controlled / disabled"} detail={`Environment ${value.environment}`} /></section><section aria-labelledby="activity-title"><div className="section-heading"><h2 id="activity-title">Audit activity</h2><Link to="/admin/audit">Open full Audit Ledger</Link></div><div className="card-grid metrics-grid">{metrics.map(([label, metric]) => <article className="metric-card" key={String(label)}><span>{label}</span><strong>{metric}</strong></article>)}</div></section><section aria-labelledby="recent-title"><div className="section-heading"><h2 id="recent-title">Recent activity</h2><Link to="/admin/audit">Investigate all events</Link></div>{value.recent_events.length ? <ol className="recent-list">{value.recent_events.map((event) => <li key={event.event_id}><time dateTime={event.occurred_at_utc}>{formatTime(event.occurred_at_utc)}</time><EventLink event={event} /><span>{event.actor.display_name ?? event.actor.type} · {event.result}</span></li>)}</ol> : <p className="state-note">No audit events have been recorded.</p>}</section><section className="shortcuts" aria-label="Administrator shortcuts"><Link to="/admin/audit">Full Audit Ledger</Link><Link to="/admin/system">System status</Link><Link to="/admin/diagnostics">Diagnostics</Link></section></>;
}

function StatusCard({ label, value, detail }: { label: string; value: string; detail: string }) { return <article className="status-card"><span>{label}</span><strong>{value}</strong><small>{detail}</small></article>; }

const filterNames = ["start", "end", "actor", "action", "action_category", "entity_type", "entity_id", "result", "source", "request_id", "correlation_id", "search", "current_user_changes", "security_events_only", "administrative_events_only", "page", "page_size"];

function validAuditParams(raw: URLSearchParams) {
  const params = new URLSearchParams();
  filterNames.forEach((name) => {
    const value = raw.get(name);
    if (value && value.length <= 255) params.set(name, value);
  });
  const page = Number(params.get("page") ?? "1");
  if (!Number.isInteger(page) || page < 1) params.set("page", "1");
  const size = Number(params.get("page_size") ?? "50");
  if (!Number.isInteger(size) || size < 1 || size > 250) params.set("page_size", "50");
  return params;
}

function setFilter(params: URLSearchParams, name: string, value: string) {
  const next = new URLSearchParams(params);
  if (value) next.set(name, value);
  else next.delete(name);
  next.set("page", "1");
  return next;
}

function AuditPage() {
  const [searchParams, setSearchParams] = useSearchParams();
  const params = useMemo(() => validAuditParams(searchParams), [searchParams]);
  const catalog = useRemote<AuditCatalog>((signal) => adminApi.catalog(signal), "catalog");
  const ledger = useRemote<AuditList>((signal) => adminApi.audit(params, signal), params.toString());
  const update = (name: string, value: string) => setSearchParams(setFilter(params, name, value));
  if (catalog.state === "error") return <ErrorState error={catalog.error} />;
  if (ledger.state === "error") return <ErrorState error={ledger.error} />;
  return <><PageTitle title="Global Audit Ledger"><p>Authoritative immutable evidence. Filters, sorting, and pagination are executed by the server.</p></PageTitle><AuditFilters params={params} update={update} catalog={catalog.state === "ready" ? catalog.value : undefined} /><section aria-live="polite">{ledger.state === "loading" ? <LoadingState /> : <AuditTable result={ledger.value} params={params} setSearchParams={setSearchParams} />}</section></>;
}

function AuditFilters({ params, update, catalog }: { params: URLSearchParams; update: (name: string, value: string) => void; catalog?: AuditCatalog }) {
  const today = new Date();
  today.setUTCHours(0, 0, 0, 0);
  const toggle = (name: "current_user_changes" | "security_events_only" | "administrative_events_only") => update(name, params.get(name) === "true" ? "" : "true");
  return <section className="filters" aria-labelledby="filter-title"><div className="section-heading"><h2 id="filter-title">Investigate events</h2><button type="button" className="link-button" onClick={() => update("search", "")}>Clear search</button></div><div className="filter-grid"><label>Search safe evidence<input value={params.get("search") ?? ""} onChange={(e) => update("search", e.target.value)} placeholder="Event, actor, request, or entity" /></label><label>Start (UTC)<input type="datetime-local" value={params.get("start")?.slice(0, 16) ?? ""} onChange={(e) => update("start", e.target.value ? `${e.target.value}:00Z` : "")} /></label><label>End (UTC)<input type="datetime-local" value={params.get("end")?.slice(0, 16) ?? ""} onChange={(e) => update("end", e.target.value ? `${e.target.value}:00Z` : "")} /></label><Select label="Action" value={params.get("action") ?? ""} values={catalog?.actions} onChange={(value) => update("action", value)} /><Select label="Category" value={params.get("action_category") ?? ""} values={catalog?.action_categories} onChange={(value) => update("action_category", value)} /><Select label="Entity type" value={params.get("entity_type") ?? ""} values={catalog?.entity_types} onChange={(value) => update("entity_type", value)} /><Select label="Result" value={params.get("result") ?? ""} values={catalog?.results} onChange={(value) => update("result", value)} /><Select label="Source" value={params.get("source") ?? ""} values={catalog?.sources} onChange={(value) => update("source", value)} /><label>Actor<input value={params.get("actor") ?? ""} onChange={(e) => update("actor", e.target.value)} /></label><label>Entity ID<input value={params.get("entity_id") ?? ""} onChange={(e) => update("entity_id", e.target.value)} /></label><label>Request ID<input value={params.get("request_id") ?? ""} onChange={(e) => update("request_id", e.target.value)} /></label><label>Correlation ID<input value={params.get("correlation_id") ?? ""} onChange={(e) => update("correlation_id", e.target.value)} /></label><Select label="Page size" value={params.get("page_size") ?? "50"} values={["25", "50", "100", "250"]} onChange={(value) => update("page_size", value || "50")} /></div><div className="preset-row"><button type="button" onClick={() => update("start", today.toISOString())}>Today (UTC)</button><button type="button" onClick={() => update("start", new Date(Date.now() - 3600_000).toISOString())}>Last hour</button><button type="button" onClick={() => update("start", new Date(Date.now() - 86_400_000).toISOString())}>Last 24 hours</button><button type="button" onClick={() => update("start", new Date(Date.now() - 7 * 86_400_000).toISOString())}>Last 7 days</button><button type="button" onClick={() => update("result", "FAILURE")}>Failed</button><button type="button" onClick={() => update("result", "DENIED")}>Denied</button><button type="button" aria-pressed={params.get("current_user_changes") === "true"} onClick={() => toggle("current_user_changes")}>My activity</button><button type="button" aria-pressed={params.get("security_events_only") === "true"} onClick={() => toggle("security_events_only")}>Security / authentication</button><button type="button" aria-pressed={params.get("administrative_events_only") === "true"} onClick={() => toggle("administrative_events_only")}>Administrative operations</button></div></section>;
}

function Select({ label, value, values, onChange }: { label: string; value: string; values?: string[]; onChange: (value: string) => void }) { return <label>{label}<select value={value} onChange={(e) => onChange(e.target.value)}>{label === "Page size" ? null : <option value="">All</option>}{(values ?? []).map((option) => <option key={option} value={option}>{option.replaceAll("_", " ")}</option>)}</select></label>; }

function AuditTable({ result, params, setSearchParams }: { result: AuditList; params: URLSearchParams; setSearchParams: (next: URLSearchParams) => void }) {
  const pages = Math.max(1, Math.ceil(result.total / result.page_size));
  const goTo = (page: number) => { const next = new URLSearchParams(params); next.set("page", String(page)); setSearchParams(next); };
  return <><div className="table-summary"><span>{result.total} matching event{result.total === 1 ? "" : "s"}</span><span>Order: persisted time, then persisted sequence</span></div>{result.items.length ? <div className="audit-table-wrap"><table className="audit-table"><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Entity</th><th>Changed fields</th><th>Result</th><th>Source</th></tr></thead><tbody>{result.items.map((event) => <tr key={event.event_id}><td data-label="Time"><time dateTime={event.occurred_at_utc}>{formatTime(event.occurred_at_utc)}</time></td><td data-label="Actor">{event.actor.display_name ?? event.actor.type}</td><td data-label="Action"><EventLink event={event} /></td><td data-label="Entity">{event.entity.type} · {event.entity.display_id ?? event.entity.id}</td><td data-label="Changed fields">{event.changed_fields.join(", ") || "—"}</td><td data-label="Result"><span className={`result result-${event.result.toLowerCase()}`}>{event.result}</span></td><td data-label="Source">{event.source_client}</td></tr>)}</tbody></table></div> : <p className="state-note">No audit events match these filters.</p>}<nav className="pagination" aria-label="Audit pagination"><button type="button" disabled={result.page <= 1} onClick={() => goTo(result.page - 1)}>Previous</button><span>Page {result.page} of {pages}</span><button type="button" disabled={result.page >= pages} onClick={() => goTo(result.page + 1)}>Next</button></nav></>;
}

function EventDetailPage() {
  const { eventId = "" } = useParams();
  const navigate = useNavigate();
  const remote = useRemote<AuditEvent>((signal) => adminApi.event(eventId, signal), `event:${eventId}`);
  if (remote.state === "loading") return <LoadingState />;
  if (remote.state === "error") return <ErrorState error={remote.error} />;
  const event = remote.value;
  const entityPath = entityLink(event);
  return <><PageTitle title="Audit event detail"><button type="button" className="link-button" onClick={() => navigate(-1)}>← Back to investigation</button></PageTitle><section className="detail-summary"><Detail label="Event ID" value={event.event_id} copyable /><Detail label="Occurred" value={`${formatTime(event.occurred_at_utc)} (UTC: ${event.occurred_at_utc})`} /><Detail label="Action" value={`${event.action} · ${event.action_category}`} /><Detail label="Result" value={event.result} /><Detail label="Source" value={event.source_client} /></section><section className="detail-grid"><article><h2>Actor</h2><Detail label="Display" value={event.actor.display_name ?? "Not recorded"} /><Detail label="Type" value={event.actor.type} /><Detail label="Stable ID" value={event.actor.id ?? "Not recorded"} /><Detail label="Directory identity" value={event.actor.directory_name ?? "Not recorded"} /></article><article><h2>Entity</h2><Detail label="Type" value={event.entity.type} /><Detail label="Stable ID" value={event.entity.id} /><Detail label="Display ID" value={event.entity.display_id ?? "Not recorded"} />{entityPath ? <Link to={entityPath}>Open normal profile</Link> : <p className="state-note">No canonical normal-profile link is available for this entity type.</p>}</article></section><section><h2>Structured change evidence</h2><AuditDiff changedFields={event.changed_fields} before={event.before} after={event.after} /></section>{event.reason_or_note ? <section><h2>Reason or note</h2><p>{event.reason_or_note}</p></section> : null}<section className="detail-grid"><article><h2>Request context</h2><Detail label="Request ID" value={event.request_id ?? "Not recorded"} copyable link={event.request_id ? `/admin/audit?request_id=${encodeURIComponent(event.request_id)}` : undefined} /><Detail label="Correlation ID" value={event.correlation_id ?? "Not recorded"} copyable link={event.correlation_id ? `/admin/audit?correlation_id=${encodeURIComponent(event.correlation_id)}` : undefined} /><Detail label="Transaction ID" value={event.transaction_id ?? "Not recorded"} /><Detail label="Operation" value={event.operation ?? "Not recorded"} /></article><article><h2>Related activity</h2>{event.correlation_id ? <RelatedEvents correlationId={event.correlation_id} currentEventId={event.event_id} /> : <p className="state-note">This event has no recorded correlation ID.</p>}</article></section></>;
}

function RelatedEvents({ correlationId, currentEventId }: { correlationId: string; currentEventId: string }) {
  const params = useMemo(() => new URLSearchParams({ correlation_id: correlationId, page_size: "10" }), [correlationId]);
  const remote = useRemote<AuditList>((signal) => adminApi.audit(params, signal), `related:${correlationId}`);
  const filtered = remote.state === "ready" ? remote.value.items.filter((item) => item.event_id !== currentEventId) : [];
  return <>{remote.state === "loading" ? <p className="state-note">Loading correlated events…</p> : null}{remote.state === "error" ? <p className="state-note">Related events could not load. Request ID: {remote.error.requestId ?? "not available"}</p> : null}{remote.state === "ready" && filtered.length ? <ol className="related-list">{filtered.map((item) => <li key={item.event_id}><EventLink event={item} /><span>{formatTime(item.occurred_at_utc)} · {item.result}</span></li>)}</ol> : null}{remote.state === "ready" && !filtered.length ? <p className="state-note">No other events share this correlation ID.</p> : null}<Link to={`/admin/audit?correlation_id=${encodeURIComponent(correlationId)}`}>View all events with this correlation ID</Link></>;
}

function entityLink(event: AuditEvent) {
  const identifier = event.entity.display_id?.trim();
  if (!identifier) return undefined;
  const prefix = { eoat: "/eoats/", machine: "/machines/", tool: "/tools/" }[event.entity.type.toLowerCase()];
  return prefix ? `${prefix}${encodeURIComponent(identifier)}` : undefined;
}
function Detail({ label, value, copyable = false, link }: { label: string; value: string; copyable?: boolean; link?: string }) { return <dl className="detail"><dt>{label}</dt><dd>{link ? <Link to={link}>{value}</Link> : <code>{value}</code>}{copyable && value !== "Not recorded" ? <button type="button" className="link-button" onClick={() => copy(value)}>Copy</button> : null}</dd></dl>; }

function DiagnosticsPage({ diagnostics = false }: { diagnostics?: boolean }) { const remote = useRemote<AdminDiagnostics>((signal) => diagnostics ? adminApi.diagnostics(signal) : adminApi.system(signal), diagnostics ? "diagnostics" : "system"); if (remote.state === "loading") return <LoadingState />; if (remote.state === "error") return <ErrorState error={remote.error} />; const value = remote.value; return <><PageTitle title={diagnostics ? "Diagnostics" : "System status"}><p>Safe read-only operational information observed at {formatTime(value.observation_time_utc)}.</p></PageTitle><section className="card-grid status-grid"><StatusCard label="API" value={value.api_status} detail="Server response" /><StatusCard label="Database" value={value.database_status} detail={`Schema ${value.schema_revision ?? "unknown"}`} /><StatusCard label="Audit" value={value.audit_status} detail={value.compatible ? "Schema compatible" : `Expected ${value.expected_schema_revision ?? "unknown"}`} /></section><p className="state-note">Diagnostics do not provide SQL, shell, filesystem, log-browsing, or mutation capabilities.</p></>; }

function SessionGate({ onReady }: { onReady: () => void }) {
  const [identity, setIdentity] = useState(import.meta.env.VITE_EOAT_IDENTITY ?? "dev.admin");
  const [rehearsalSecret, setRehearsalSecret] = useState("");
  const [error, setError] = useState<AdminApiError | undefined>();
  const [busy, setBusy] = useState(false);
  const start = () => { setBusy(true); setError(undefined); adminApi.startRehearsal(identity, rehearsalSecret).then(() => { setRehearsalSecret(""); onReady(); }).catch((value: unknown) => setError(value instanceof AdminApiError ? value : new AdminApiError("The development/test session could not start.", 0))).finally(() => setBusy(false)); };
  return <section className="state-panel"><h1>Start development/test Administrator session</h1><p>This local rehearsal session is separate from production corporate authentication. Its CSRF proof remains only in this browser memory; the actor is resolved from the HttpOnly server session for every governed mutation.</p><label>Configured development/test identity<input value={identity} onChange={(event) => setIdentity(event.target.value)} autoComplete="off" /></label><label>Development/test rehearsal secret<input type="password" value={rehearsalSecret} onChange={(event) => setRehearsalSecret(event.target.value)} autoComplete="current-password" /></label><button className="primary-button" type="button" disabled={busy || rehearsalSecret.length < 16} onClick={start}>{busy ? "Starting…" : "Start governed session"}</button>{error ? <p className="inline-error">{error.message}{error.requestId ? ` Request ID: ${error.requestId}` : ""}</p> : null}</section>;
}

const editorFields: Record<string, Array<[string, string]>> = {
  eoats: [["display_name", "Display name"], ["description", "Description"], ["revision", "Revision"], ["manufacturer", "Manufacturer"], ["number_of_parts_picked", "Parts picked"], ["number_of_vacuum_cups", "Vacuum cups"], ["number_of_grippers", "Grippers"], ["notes", "Notes"]],
  machines: [["machine_name", "Machine name"], ["manufacturer", "Manufacturer"], ["model", "Model"], ["serial_number", "Serial number"], ["machine_type", "Machine type"], ["press_capacity_tons", "Press capacity (tons)"], ["controller_type", "Controller type"], ["notes", "Notes"]],
  tools: [["tool_number", "Tool number"], ["mold_number", "Mold number"], ["display_name", "Display name"], ["description", "Description"], ["cavity_count", "Cavity count"], ["tool_type", "Tool type"], ["customer", "Customer"], ["program_name", "Program"], ["notes", "Notes"]],
};

function AuditSuccess({ eventId }: { eventId?: string }) { return eventId ? <p className="success-note">Committed with immutable evidence. <Link to={`/admin/audit/events/${encodeURIComponent(eventId)}`}>View Audit Event</Link></p> : null; }

function AssetEditor({ kind, record, onCommitted }: { kind: "eoats" | "machines" | "tools"; record: AdminRecord; onCommitted: (auditEventId: string) => void }) {
  const identifier = String(record[kind === "machines" ? "machine_number" : "business_identifier"] ?? "");
  const [values, setValues] = useState<Record<string, AuditValue>>({});
  const [reason, setReason] = useState(""); const [correction, setCorrection] = useState(false); const [confirmation, setConfirmation] = useState("");
  const [preview, setPreview] = useState<{ changed_fields: string[]; before: Record<string, AuditValue>; after: Record<string, AuditValue> } | undefined>();
  const [error, setError] = useState<AdminApiError | undefined>(); const [busy, setBusy] = useState(false); const [audit, setAudit] = useState<string>();
  useEffect(() => { setValues(Object.fromEntries(editorFields[kind].map(([field]) => [field, record[field] ?? ""]))); setPreview(undefined); setError(undefined); setAudit(undefined); setReason(""); setCorrection(false); setConfirmation(""); }, [kind, record]);
  const payload = (): Record<string, AuditValue> => {
    const changed = Object.fromEntries(Object.entries(values).filter(([field, value]) => String(value ?? "") !== String(record[field] ?? "")));
    return { ...changed, expected_row_version: Number(record.row_version ?? 0), ...(correction ? { reason } : {}) };
  };
  const previewChange = () => { setBusy(true); setError(undefined); adminApi.previewAsset(kind, identifier, payload()).then(setPreview).catch((value: unknown) => setError(value instanceof AdminApiError ? value : new AdminApiError("Preview failed.", 0))).finally(() => setBusy(false)); };
  const commit = () => { if (!preview?.changed_fields.length) return; setBusy(true); setError(undefined); adminApi.updateAsset(kind, identifier, payload(), correction).then((result) => { setAudit(result.audit_event_id); onCommitted(result.audit_event_id); }).catch((value: unknown) => setError(value instanceof AdminApiError ? value : new AdminApiError("Commit failed.", 0))).finally(() => setBusy(false)); };
  const lifecycle = (action: "archive" | "restore") => { setBusy(true); setError(undefined); adminApi.lifecycleAsset(kind, identifier, action, { expected_row_version: Number(record.row_version ?? 0), reason: reason || `${action} requested through governed Administrator workflow`, confirmation }).then((result) => { setAudit(result.audit_event_id); onCommitted(result.audit_event_id); }).catch((value: unknown) => setError(value instanceof AdminApiError ? value : new AdminApiError("Lifecycle action failed.", 0))).finally(() => setBusy(false)); };
  return <section className="editor-card"><div className="section-heading"><h2>{identifier}</h2><a href={`/${kind}/${encodeURIComponent(identifier)}`}>Open normal profile</a></div><p className="state-note">Stable identity, database ID, audit fields, timestamps, and row version are read-only. Current revision: {String(record.row_version ?? "unknown")}.</p><div className="editor-grid">{editorFields[kind].map(([field, label]) => <label key={field}>{label}<input type={field.includes("count") || field.includes("capacity") || field.includes("picked") || field.includes("cups") || field.includes("grippers") ? "number" : "text"} value={String(values[field] ?? "")} onChange={(event) => setValues({ ...values, [field]: event.target.value === "" ? null : (event.target.type === "number" ? Number(event.target.value) : event.target.value) })} /></label>)}</div><label className="check-row"><input type="checkbox" checked={correction} onChange={(event) => setCorrection(event.target.checked)} /> Record this as a correction that preserves the prior evidence</label>{correction ? <label>Correction reason<input value={reason} onChange={(event) => setReason(event.target.value)} required /></label> : null}<div className="editor-actions"><button type="button" onClick={previewChange} disabled={busy}>Preview material change</button><button className="primary-button" type="button" onClick={commit} disabled={busy || !preview?.changed_fields.length || (correction && reason.trim().length < 3)}>{busy ? "Submitting…" : "Commit governed edit"}</button></div>{preview ? <section className="preview-panel" aria-live="polite"><h3>Material change preview</h3>{preview.changed_fields.length ? <ul>{preview.changed_fields.map((field) => <li key={field}><strong>{field}</strong>: {String(preview.before[field] ?? "unknown")} → {String(preview.after[field] ?? "unknown")}</li>)}</ul> : <p>No material changes are ready to commit.</p>}</section> : null}<section className="lifecycle-panel"><h3>Archive or restore</h3><p>Archive is reversible and subject to domain constraints. Type <code>ARCHIVE {identifier}</code> or <code>RESTORE {identifier}</code> before continuing.</p><label>Typed confirmation<input value={confirmation} onChange={(event) => setConfirmation(event.target.value)} /></label><div className="editor-actions"><button type="button" disabled={busy || confirmation !== `ARCHIVE ${identifier}`} onClick={() => lifecycle("archive")}>Archive record</button><button type="button" disabled={busy || confirmation !== `RESTORE ${identifier}`} onClick={() => lifecycle("restore")}>Restore record</button></div></section>{error ? <p className="inline-error">{error.message}{error.code === "STALE_RECORD_VERSION" ? " This record changed after you opened it; reload the latest values and reapply manually." : ""}</p> : null}<AuditSuccess eventId={audit} /></section>;
}

function DataPage({ initialKind = "eoats" }: { initialKind?: "eoats" | "machines" | "tools" }) {
  const { ready, setReady } = useAdminSession(); const [kind, setKind] = useState<"eoats" | "machines" | "tools">(initialKind); const [search, setSearch] = useState(""); const [selected, setSelected] = useState<AdminRecord>(); const [refresh, setRefresh] = useState(0); const [lastAuditEvent, setLastAuditEvent] = useState<string>();
  useEffect(() => { setKind(initialKind); setSelected(undefined); }, [initialKind]);
  const remote = useRemote<{ items: AdminRecord[] }>(() => adminApi.assets(kind, search), `assets:${ready}:${kind}:${search}:${refresh}`);
  if (!ready) return <SessionGate onReady={() => setReady(true)} />;
  if (remote.state === "error") return <ErrorState error={remote.error} />;
  return <><PageTitle title="Governed data management"><p>Use authoritative records and domain-aware fields. Preview first, then commit only a material, capability-authorized change with immutable Audit evidence.</p></PageTitle><AuditSuccess eventId={lastAuditEvent} /><section className="filters"><div className="filter-grid"><Select label="Record type" value={kind} values={["eoats", "machines", "tools"]} onChange={(value) => { setKind(value as typeof kind); setSelected(undefined); }} /><label>Server-backed search<input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Identifier, name, or description" /></label></div></section>{remote.state === "loading" ? <LoadingState /> : <div className="management-grid"><section className="record-list" aria-label="Authoritative records">{remote.value.items.map((item) => { const id = String(item[kind === "machines" ? "machine_number" : "business_identifier"] ?? ""); return <button type="button" key={id} className={selected === item ? "selected" : ""} onClick={() => setSelected(item)}><strong>{id}</strong><span>{String(item.display_name ?? item.machine_name ?? item.tool_number ?? "Unnamed")}</span></button>; })}{!remote.value.items.length ? <p className="state-note">No records match the current search.</p> : null}</section>{selected ? <AssetEditor kind={kind} record={selected} onCommitted={(auditEventId) => { setLastAuditEvent(auditEventId); setSelected(undefined); setRefresh(refresh + 1); }} /> : <p className="state-note">Select one record to inspect, preview, correct, archive, or restore.</p>}</div>}</>;
}

function DocumentsPage() { const { ready, setReady } = useAdminSession(); const [refresh, setRefresh] = useState(0); const remote = useRemote<{ items: AdminRecord[] }>(() => adminApi.documents(), `documents:${ready}:${refresh}`); if (!ready) return <SessionGate onReady={() => setReady(true)} />; if (remote.state === "error") return <ErrorState error={remote.error} />; if (remote.state === "loading") return <LoadingState />; return <><PageTitle title="Governed document metadata"><p>Documents are server-resolved records. File locations, checksums, and storage internals are intentionally never shown or accepted in this Administrator surface.</p></PageTitle><div className="settings-list">{remote.value.items.map((record) => <DocumentEditor key={String(record.id)} record={record} onDone={() => setRefresh(refresh + 1)} />)}{!remote.value.items.length ? <p className="state-note">No active documents are available in this environment.</p> : null}</div></>; }
function DocumentEditor({ record, onDone }: { record: AdminRecord; onDone: () => void }) { const documentId = Number(record.id); const [title, setTitle] = useState(String(record.title ?? "")); const [reason, setReason] = useState(""); const [confirmation, setConfirmation] = useState(""); const [audit, setAudit] = useState<string>(); const [error, setError] = useState<AdminApiError>(); const update = () => adminApi.updateDocument(documentId, { title, expected_row_version: Number(record.row_version), reason: reason || null }).then((value) => { setAudit(value.audit_event_id); onDone(); }).catch((value: unknown) => setError(value instanceof AdminApiError ? value : new AdminApiError("Document update failed.", 0))); const archive = () => adminApi.archiveDocument(documentId, { expected_row_version: Number(record.row_version), reason, confirmation }).then((value) => { setAudit(value.audit_event_id); onDone(); }).catch((value: unknown) => setError(value instanceof AdminApiError ? value : new AdminApiError("Document archive failed.", 0))); return <section className="editor-card"><h2>{String(record.document_number ?? record.title ?? `Document ${documentId}`)}</h2><p>Revision {String(record.revision ?? "not recorded")} · row version {String(record.row_version)}</p><label>Title<input value={title} onChange={(event) => setTitle(event.target.value)} /></label><label>Reason (optional for metadata)<input value={reason} onChange={(event) => setReason(event.target.value)} /></label><button className="primary-button" type="button" onClick={update}>Save metadata</button><label>To archive, type <code>ARCHIVE DOCUMENT {documentId}</code><input value={confirmation} onChange={(event) => setConfirmation(event.target.value)} /></label><button type="button" disabled={reason.trim().length < 3 || confirmation !== `ARCHIVE DOCUMENT ${documentId}`} onClick={archive}>Archive document</button>{error ? <p className="inline-error">{error.message}</p> : null}<AuditSuccess eventId={audit} /></section>; }

function PhotosPage() { const { ready, setReady } = useAdminSession(); const [refresh, setRefresh] = useState(0); const remote = useRemote<{ items: Array<{ photo: AdminRecord; document: AdminRecord; row_version: number }> }>(() => adminApi.photos(), `photos:${ready}:${refresh}`); if (!ready) return <SessionGate onReady={() => setReady(true)} />; if (remote.state === "error") return <ErrorState error={remote.error} />; if (remote.state === "loading") return <LoadingState />; return <><PageTitle title="Governed photo metadata"><p>Photo metadata is editable and archiveable; binary locations and file internals remain outside the browser administration surface.</p></PageTitle><div className="settings-list">{remote.value.items.map((value) => <PhotoEditor key={String(value.photo.id)} value={value} onDone={() => setRefresh(refresh + 1)} />)}{!remote.value.items.length ? <p className="state-note">No active photos are available in this environment.</p> : null}</div></>; }
function PhotoEditor({ value, onDone }: { value: { photo: AdminRecord; document: AdminRecord; row_version: number }; onDone: () => void }) { const photoId = Number(value.photo.id); const [caption, setCaption] = useState(String(value.photo.caption ?? "")); const [reason, setReason] = useState(""); const [confirmation, setConfirmation] = useState(""); const [audit, setAudit] = useState<string>(); const [error, setError] = useState<AdminApiError>(); const update = () => adminApi.updatePhoto(photoId, { caption, expected_row_version: value.row_version, reason: reason || null }).then((result) => { setAudit(result.audit_event_id); onDone(); }).catch((result: unknown) => setError(result instanceof AdminApiError ? result : new AdminApiError("Photo update failed.", 0))); const archive = () => adminApi.archivePhoto(photoId, { expected_row_version: value.row_version, reason, confirmation }).then((result) => { setAudit(result.audit_event_id); onDone(); }).catch((result: unknown) => setError(result instanceof AdminApiError ? result : new AdminApiError("Photo archive failed.", 0))); return <section className="editor-card"><h2>{String(value.document.title ?? `Photo ${photoId}`)}</h2><label>Caption<input value={caption} onChange={(event) => setCaption(event.target.value)} /></label><label>Reason<input value={reason} onChange={(event) => setReason(event.target.value)} /></label><button className="primary-button" type="button" onClick={update}>Save photo metadata</button><label>To archive, type <code>ARCHIVE PHOTO {photoId}</code><input value={confirmation} onChange={(event) => setConfirmation(event.target.value)} /></label><button type="button" disabled={reason.trim().length < 3 || confirmation !== `ARCHIVE PHOTO ${photoId}`} onClick={archive}>Archive photo</button>{error ? <p className="inline-error">{error.message}</p> : null}<AuditSuccess eventId={audit} /></section>; }

function RelationshipsPage() { const { ready, setReady } = useAdminSession(); const [relationshipType, setRelationshipType] = useState("eoat-machine"); const [eoat, setEoat] = useState(""); const [machine, setMachine] = useState(""); const [tool, setTool] = useState(""); const [status, setStatus] = useState(""); const [reason, setReason] = useState(""); const [audit, setAudit] = useState<string>(); const [error, setError] = useState<AdminApiError>(); const catalog = useRemote<{ eoats: AdminRecord[]; machines: AdminRecord[]; tools: AdminRecord[]; statuses: Array<{ code: string; display_name: string }> }>(async () => { const [eoats, machines, tools, statuses] = await Promise.all([adminApi.assets("eoats"), adminApi.assets("machines"), adminApi.assets("tools"), adminApi.lookup("compatibility_statuses")]); return { eoats: eoats.items, machines: machines.items, tools: tools.items, statuses }; }, `relationship-selectors:${ready}`); const relations = useRemote<{ items: AdminRecord[] }>(() => adminApi.relationships(relationshipType), `relationships:${ready}:${relationshipType}:${audit ?? ""}`); const targetIdentifiers = relationshipType === "eoat-machine" ? { eoat_identifier: eoat, machine_number: machine } : relationshipType === "eoat-tool" ? { eoat_identifier: eoat, tool_identifier: tool } : { tool_identifier: tool, machine_number: machine }; const commit = () => adminApi.linkRelationship(relationshipType, { ...targetIdentifiers, compatibility_status: status, verification_source: "user_verified", effective_from: new Date().toISOString(), reason: reason || null, confirmation: `LINK ${relationshipType}` }).then((value) => setAudit(value.audit_event_id)).catch((value: unknown) => setError(value instanceof AdminApiError ? value : new AdminApiError("Relationship update failed.", 0))); if (!ready) return <SessionGate onReady={() => setReady(true)} />; if (catalog.state === "error") return <ErrorState error={catalog.error} />; if (catalog.state === "loading" || relations.state === "loading") return <LoadingState />; if (relations.state === "error") return <ErrorState error={relations.error} />; const showEoat = relationshipType !== "tool-machine"; const showMachine = relationshipType !== "eoat-tool"; const showTool = relationshipType !== "eoat-machine"; return <><PageTitle title="Governed relationship management"><p>Relationship creation uses selected, authoritative business identifiers and compatibility status; the API resolves and validates every target before committing a link.</p></PageTitle><section className="editor-card"><Select label="Relationship type" value={relationshipType} values={["eoat-machine", "eoat-tool", "tool-machine"]} onChange={setRelationshipType} />{showEoat ? <label>EOAT<select value={eoat} onChange={(event) => setEoat(event.target.value)}><option value="">Select an EOAT</option>{catalog.value.eoats.map((row) => <option key={String(row.business_identifier)} value={String(row.business_identifier)}>{String(row.business_identifier)}</option>)}</select></label> : null}{showMachine ? <label>Machine<select value={machine} onChange={(event) => setMachine(event.target.value)}><option value="">Select a Machine</option>{catalog.value.machines.map((row) => <option key={String(row.machine_number)} value={String(row.machine_number)}>{String(row.machine_number)}</option>)}</select></label> : null}{showTool ? <label>Tool<select value={tool} onChange={(event) => setTool(event.target.value)}><option value="">Select a Tool</option>{catalog.value.tools.map((row) => <option key={String(row.business_identifier)} value={String(row.business_identifier)}>{String(row.business_identifier)}</option>)}</select></label> : null}<label>Compatibility status<select value={status} onChange={(event) => setStatus(event.target.value)}><option value="">Select an authoritative compatibility status</option>{catalog.value.statuses.map((value) => <option key={value.code} value={value.code}>{value.display_name}</option>)}</select></label><label>Reason (optional)<input value={reason} onChange={(event) => setReason(event.target.value)} /></label><p className="state-note">Typed confirmation is server-derived: <code>LINK {relationshipType}</code>.</p><button className="primary-button" type="button" disabled={(showEoat && !eoat) || (showMachine && !machine) || (showTool && !tool) || !status} onClick={commit}>Validate and link relationship</button>{error ? <p className="inline-error">{error.message}</p> : null}<AuditSuccess eventId={audit} /></section><section className="editor-card"><h2>Current relationships</h2>{relations.value.items.map((row) => <RelationshipUnlinkEditor key={String(row.id)} relationshipType={relationshipType} row={row} />)}{!relations.value.items.length ? <p className="state-note">No current relationships of this type.</p> : null}</section></>; }
function RelationshipUnlinkEditor({ relationshipType, row }: { relationshipType: string; row: AdminRecord }) { const [reason, setReason] = useState(""); const [confirmation, setConfirmation] = useState(""); const [audit, setAudit] = useState<string>(); const [error, setError] = useState<AdminApiError>(); const label = `${String(row.left)} ↔ ${String(row.right)}`; const expected = `UNLINK ${relationshipType}:${Number(row.id)}`; const unlink = () => adminApi.unlinkRelationship(relationshipType, Number(row.id), { expected_row_version: Number(row.row_version), reason, confirmation }).then((value) => setAudit(value.audit_event_id)).catch((value: unknown) => setError(value instanceof AdminApiError ? value : new AdminApiError("Relationship unlink failed.", 0))); return <div className="lifecycle-panel"><strong>{label}</strong><span> · revision {String(row.row_version)}</span><label>Unlink reason<input value={reason} onChange={(event) => setReason(event.target.value)} /></label><label>Type <code>{expected}</code><input value={confirmation} onChange={(event) => setConfirmation(event.target.value)} /></label><button type="button" disabled={reason.trim().length < 3 || confirmation !== expected} onClick={unlink}>Unlink relationship</button>{error ? <p className="inline-error">{error.message}</p> : null}<AuditSuccess eventId={audit} /></div>; }

function BulkStatusPage() { const { ready, setReady } = useAdminSession(); const [identifiersText, setIdentifiersText] = useState(""); const [status, setStatus] = useState("active"); const [reason, setReason] = useState(""); const [confirmation, setConfirmation] = useState(""); const [preview, setPreview] = useState<{ count: number; records: AdminRecord[]; atomic: boolean }>(); const [audit, setAudit] = useState<string>(); const [error, setError] = useState<AdminApiError>(); const assets = useRemote<{ items: AdminRecord[] }>(() => adminApi.assets("eoats"), `bulk-assets:${ready}`); const identifiers = identifiersText.split(/[\s,]+/).map((value) => value.trim()).filter(Boolean); const expectedVersions = Object.fromEntries((assets.state === "ready" ? assets.value.items : []).filter((row) => identifiers.includes(String(row.business_identifier))).map((row) => [String(row.business_identifier), Number(row.row_version)])); const previewChange = () => adminApi.previewBulkStatus({ identifiers, status, expected_versions: expectedVersions }).then(setPreview).catch((value: unknown) => setError(value instanceof AdminApiError ? value : new AdminApiError("Bulk preview failed.", 0))); const commit = () => adminApi.commitBulkStatus({ identifiers, status, expected_versions: expectedVersions, reason, confirmation }).then((value) => setAudit(value.audit_event_id)).catch((value: unknown) => setError(value instanceof AdminApiError ? value : new AdminApiError("Bulk commit failed.", 0))); if (!ready) return <SessionGate onReady={() => setReady(true)} />; if (assets.state === "error") return <ErrorState error={assets.error} />; if (assets.state === "loading") return <LoadingState />; return <><PageTitle title="EOAT bulk status workflow"><p>This is the sole bounded bulk workflow: preview first, validate every current row version, then commit atomically or leave all records unchanged.</p></PageTitle><section className="editor-card"><label>EOAT identifiers (comma or line separated)<textarea value={identifiersText} onChange={(event) => setIdentifiersText(event.target.value)} /></label><label>Status code<input value={status} onChange={(event) => setStatus(event.target.value)} /></label><button type="button" disabled={!identifiers.length || Object.keys(expectedVersions).length !== identifiers.length} onClick={previewChange}>Preview atomic bulk change</button>{preview ? <p className="state-note">Preview covers {preview.count} records atomically.</p> : null}<label>Reason<input value={reason} onChange={(event) => setReason(event.target.value)} /></label><label>Type <code>BULK STATUS {identifiers.length}</code> to commit<input value={confirmation} onChange={(event) => setConfirmation(event.target.value)} /></label><button className="primary-button" type="button" disabled={!preview || reason.trim().length < 3 || confirmation !== `BULK STATUS ${identifiers.length}`} onClick={commit}>Commit atomic bulk change</button>{error ? <p className="inline-error">{error.message}</p> : null}<AuditSuccess eventId={audit} /></section></>; }

function SettingsPage() {
  const { ready, setReady } = useAdminSession(); const [refresh, setRefresh] = useState(0); const [lastAuditEvent, setLastAuditEvent] = useState<string>(); const remote = useRemote<{ items: AdminSetting[] }>(() => adminApi.settings(), `settings:${ready}:${refresh}`);
  if (!ready) return <SessionGate onReady={() => setReady(true)} />; if (remote.state === "error") return <ErrorState error={remote.error} />; if (remote.state === "loading") return <LoadingState />;
  return <><PageTitle title="Administrator Settings"><p>Only persisted, server-declared configuration is shown. Secrets are write-only and never returned to the browser or Audit payload.</p></PageTitle><AuditSuccess eventId={lastAuditEvent} /><div className="settings-list">{remote.value.items.map((setting) => <SettingEditor key={setting.key} setting={setting} onDone={(auditEventId) => { setLastAuditEvent(auditEventId); setRefresh((value) => value + 1); }} />)}{!remote.value.items.length ? <p className="state-note">No persisted Administrator settings are configured in this environment.</p> : null}</div></>;
}

function SettingEditor({ setting, onDone }: { setting: AdminSetting; onDone: (auditEventId: string) => void }) { const secret = setting.secret_configured != null; const [value, setValue] = useState(String(setting.value ?? "")); const [error, setError] = useState<AdminApiError>(); const save = () => adminApi.updateSetting(setting.key, { value: secret ? value : (setting.value_type === "boolean" ? value === "true" : value), expected_row_version: setting.row_version }).then((result) => onDone(result.audit_event_id)).catch((reason: unknown) => setError(reason instanceof AdminApiError ? reason : new AdminApiError("Setting update failed.", 0))); return <section className="editor-card"><h2>{setting.key}</h2><p>{setting.description ?? "Server-declared Administrator setting."}{setting.restart_required ? " Restart required after commit." : ""}</p><label>{secret ? "Replacement secret" : "Value"}{setting.value_type === "boolean" && !secret ? <select value={value} onChange={(event) => setValue(event.target.value)}><option value="true">true</option><option value="false">false</option></select> : <input type={secret ? "password" : "text"} value={value} onChange={(event) => setValue(event.target.value)} autoComplete="off" />}</label><button className="primary-button" type="button" onClick={save}>Save setting</button>{error ? <p className="inline-error">{error.message}</p> : null}</section>; }

function AccessPage() { const { ready, setReady } = useAdminSession(); const [refresh, setRefresh] = useState(0); const mappings = useRemote<{ items: AdminMapping[] }>(() => adminApi.mappings(), `mappings:${ready}:${refresh}`); const sessions = useRemote<{ items: AdminRecord[] }>(() => adminApi.sessions(), `sessions:${ready}:${refresh}`); if (!ready) return <SessionGate onReady={() => setReady(true)} />; if (mappings.state === "error") return <ErrorState error={mappings.error} />; if (sessions.state === "error") return <ErrorState error={sessions.error} />; if (mappings.state === "loading" || sessions.state === "loading") return <LoadingState />; return <><PageTitle title="Development/test Access administration"><p>These mappings and sessions are local rehearsal configuration only. No corporate directory, Active Directory group, password, bind credential, or production identity mapping is displayed or changed here.</p></PageTitle><div className="settings-list">{mappings.value.items.map((mapping) => <MappingEditor key={`${mapping.environment}:${mapping.identity}`} mapping={mapping} onDone={() => setRefresh(refresh + 1)} />)}</div><section className="editor-card"><h2>Recent rehearsal sessions</h2><p>References, age/state, and revocation status are safe to inspect. Tokens and cookies are never shown.</p>{sessions.value.items.map((session) => <SessionRevokeEditor key={String(session.session_reference)} session={session} onDone={() => setRefresh(refresh + 1)} />)}{!sessions.value.items.length ? <p className="state-note">No rehearsal sessions have been issued.</p> : null}</section></>; }
function SessionRevokeEditor({ session, onDone }: { session: AdminRecord; onDone: () => void }) { const reference = String(session.session_reference); const [reason, setReason] = useState(""); const [confirmation, setConfirmation] = useState(""); const [audit, setAudit] = useState<string>(); const [error, setError] = useState<AdminApiError>(); const revoke = () => adminApi.revokeSession(reference, { reason, confirmation }).then((value) => { setAudit(value.audit_event_id); onDone(); }).catch((value: unknown) => setError(value instanceof AdminApiError ? value : new AdminApiError("Session revocation failed.", 0))); return <div className="lifecycle-panel"><strong>{reference}</strong><span> Issued {String(session.issued_at ?? "unknown")}; {session.revoked_at ? "revoked" : "active"}</span>{!session.revoked_at ? <><label>Revocation reason<input value={reason} onChange={(event) => setReason(event.target.value)} /></label><label>Type <code>REVOKE {reference}</code><input value={confirmation} onChange={(event) => setConfirmation(event.target.value)} /></label><button type="button" disabled={reason.trim().length < 3 || confirmation !== `REVOKE ${reference}`} onClick={revoke}>Revoke session</button></> : null}{error ? <p className="inline-error">{error.message}</p> : null}<AuditSuccess eventId={audit} /></div>; }
function MappingEditor({ mapping, onDone }: { mapping: AdminMapping; onDone: () => void }) { const [role, setRole] = useState(mapping.role_code); const [reason, setReason] = useState(""); const [audit, setAudit] = useState<string>(); const [error, setError] = useState<AdminApiError>(); const save = () => adminApi.updateMapping(mapping.identity, { role_code: role, expected_row_version: mapping.row_version, reason }).then((result) => { setAudit(result.audit_event_id); onDone(); }).catch((value: unknown) => setError(value instanceof AdminApiError ? value : new AdminApiError("Mapping update failed.", 0))); return <section className="editor-card"><h2>{mapping.identity}</h2><p>Environment: {mapping.environment}</p><label>Application role<select value={role} onChange={(event) => setRole(event.target.value)}>{["ADMIN_AUDITOR", "ADMIN_DATA_MANAGER", "ADMIN_SETTINGS_MANAGER", "ADMIN_ACCESS_MANAGER", "ADMINISTRATOR"].map((value) => <option key={value}>{value}</option>)}</select></label><label>Reason<input value={reason} onChange={(event) => setReason(event.target.value)} /></label><button className="primary-button" type="button" disabled={reason.trim().length < 3} onClick={save}>Save local role mapping</button>{error ? <p className="inline-error">{error.message}</p> : null}<AuditSuccess eventId={audit} /></section>; }

function NotFound() { return <section className="state-panel"><h1>Administrator page not found</h1><p>The route is not part of the implemented read-only Administration surface.</p><Link to="/admin">Return to overview</Link></section>; }

export function AdminApp() { const [ready, setReady] = useState(false); return <AdminSessionContext.Provider value={{ ready, setReady }}><AdminLayout><Routes><Route index element={<OverviewPage />} /><Route path="audit" element={<AuditPage />} /><Route path="audit/events/:eventId" element={<EventDetailPage />} /><Route path="data" element={<DataPage />} /><Route path="data/eoats" element={<DataPage initialKind="eoats" />} /><Route path="data/machines" element={<DataPage initialKind="machines" />} /><Route path="data/tools" element={<DataPage initialKind="tools" />} /><Route path="data/relationships" element={<RelationshipsPage />} /><Route path="relationships" element={<RelationshipsPage />} /><Route path="data/documents" element={<DocumentsPage />} /><Route path="documents" element={<DocumentsPage />} /><Route path="data/photos" element={<PhotosPage />} /><Route path="photos" element={<PhotosPage />} /><Route path="data/bulk" element={<BulkStatusPage />} /><Route path="bulk" element={<BulkStatusPage />} /><Route path="settings" element={<SettingsPage />} /><Route path="access" element={<AccessPage />} /><Route path="system" element={<DiagnosticsPage />} /><Route path="diagnostics" element={<DiagnosticsPage diagnostics />} /><Route path="*" element={<NotFound />} /></Routes></AdminLayout></AdminSessionContext.Provider>; }
